// Package xpprovider hands this provider to the OneUptime Crossplane
// provider (Crossplane/provider-oneuptime, generated by
// Scripts/CrossplaneProvider), which runs it in process through Crossplane's
// Upjet instead of starting Terraform. Go keeps internal/ packages to their
// own module, so this package is the one way in.
package xpprovider

import (
	"github.com/hashicorp/terraform-plugin-framework/provider"

	internalprovider "github.com/oneuptime/terraform-provider-oneuptime/internal/provider"
)

// FrameworkProvider returns a new instance of the provider, as Terraform
// starts it: unconfigured, with every resource and data source.
func FrameworkProvider(version string) provider.Provider {
	return internalprovider.New(version)()
}
